(function(root){let cached;async function load(){if(cached)return cached;const r=await fetch('tariffs.json');if(!r.ok)throw Error('Unable to load official tariff data');const d=await r.json();if(!Array.isArray(d.records))throw Error('Invalid tariff data');cached=d;return d}function parseRate(text){const s=String(text).trim();if(/^Free$/i.test(s))return 0;const m=s.match(/^(\d+(?:\.\d+)?)%$/);return m?+m[1]:null}function search(data,query){const q=query.trim().toLowerCase(),digits=q.replace(/[.\s]/g,'');if(!q)return [];if(/^\d+$/.test(digits))return data.records.filter(r=>r.code.replace(/\./g,'').startsWith(digits));const tokens=q.split(/\s+/).filter(Boolean);return data.records.filter(r=>tokens.every(w=>r.description.toLowerCase().includes(w)))}root.Tariffs={load,parseRate,search};if(typeof module!=='undefined')module.exports=root.Tariffs})(globalThis);
